def sha(raw):return hashlib.sha256(raw).hexdigest()
def strict(raw):
 def pairs(items):
  result={}
  for key,val in items:
   if key in result:raise ValueError('duplicate JSON key')
   result[key]=val
  return result
 return json.loads(raw,object_pairs_hook=pairs,parse_constant=lambda val:(_ for _ in ()).throw(ValueError('nonfinite')))
def private_read(path,limit):
 path=Path(path).absolute()
 assert path.parent.resolve(strict=True)==path.parent
 fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
 try:
  before=os.fstat(fd)
  assert stat.S_ISREG(before.st_mode) and before.st_nlink==1 and before.st_uid==os.getuid() and stat.S_IMODE(before.st_mode)==0o600 and 0<before.st_size<=limit
  with os.fdopen(fd,'rb',closefd=False) as stream:raw=stream.read(limit+1)
  after=os.fstat(fd);named=path.lstat()
  assert len(raw)==before.st_size and all(getattr(before,k)==getattr(after,k)==getattr(named,k) for k in ('st_dev','st_ino','st_size','st_mtime_ns','st_ctime_ns','st_nlink'))
 finally:os.close(fd)
 return raw
def validate_resolution(resolution,proof):
 required={'schema','action_id','intent_sha256','state','retirement_proof_sha256','verifier_sha256',
 'retired_executor','future_executor_binding','observed_utc','business_verified','automatic_replay',
 'original_task_terminal_unchanged','old_effect_replay_forbidden'}
 assert set(resolution)==required and resolution['schema']=='hepta.action-resolution.v150.2'
 assert resolution['action_id']==ACTION and resolution['intent_sha256']==INTENT_SHA
 assert resolution['state']=='confirmed_not_executed_after_executor_retirement'
 assert resolution['retirement_proof_sha256']==PROOF_SHA and resolution['verifier_sha256']==proof['verifier_sha256']
 assert resolution['retired_executor']==proof['retired_executor'] and resolution['future_executor_binding']==EXECUTOR
 assert resolution['business_verified'] is False and resolution['automatic_replay'] is False
 assert resolution['original_task_terminal_unchanged'] is True and resolution['old_effect_replay_forbidden'] is True
 assert datetime.datetime.fromisoformat(resolution['observed_utc']).tzinfo is not None
