 if previous.get('identity')!=bound['scope']:return False
 assert previous.get('request_sha256')==bound['native_request_sha256'],'original native envelope mismatch'
 assert previous.get('terminal',{}).get('status')=='provider_failed','original failed task must stay failed'
 return True
